      de: ["Bekannt als TIPNIS.", "Regenwald-Schutzgebiet.", "Heimat indigener Gemeinschaften.", "Zentrum von Umweltschutz-Debatten."],
      hu: ["TIPNIS néven ismert.", "Esőerdei természetvédelmi terület.", "Őslakos közösségek otthona.", "Környezetvédelmi viták középpontja."],
